  tag = "CertificatePackNotDeletable",
  categories = {},
  matchers = { { status = 400, message = { includes = "Bad response certificate service" } } },
  fields = { "code", "message" },
})
classes.CertificatePackNotFound = errors.define({
  tag = "CertificatePackNotFound",
  categories = {},
  matchers = { { code = 1408 }, { status = 404 } },
  fields = { "code", "message" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = {},
  matchers = { { status = 403 } },
  fields = { "code", "message" },
})

